internal enum class RecipeCategory { STARTERS, MAINS, DESSERTS, DRINKS; fun label(): String = when (this) { STARTERS -> tr("Entrées", "Starters"); MAINS -> tr("Plats", "Mains"); DESSERTS -> tr("Desserts", "Desserts"); DRINKS -> tr("Boissons", "Drinks") } }
internal data class Recipe(val id: String, val titleFr: String, val titleEn: String, val category: RecipeCategory, val minutes: Int, val servings: Int, val ingredientsFr: List<String>, val ingredientsEn: List<String>, val stepsFr: List<String>, val stepsEn: List<String>, val allergensFr: String, val allergensEn: String) { fun name() = tr(titleFr, titleEn); fun ingredients() = if (AppLanguage.current == AppLocale.ENGLISH) ingredientsEn else ingredientsFr; fun steps() = if (AppLanguage.current == AppLocale.ENGLISH) stepsEn else stepsFr; fun allergens() = tr(allergensFr, allergensEn) }
